#include <print>
#include <memory>
#include <utility>

struct MiniVec {
    std::unique_ptr<int[]> d;
    int n = 0, cap = 0, moves = 0;
    void push(int v) {
        if (n < cap) { d[n++] = v; return; }
        auto nd = std::make_unique<int[]>(cap ? cap * 2 : 2);
        for (int i = 0; i < n; ++i) nd[i] = d[i];
        moves += n; d = std::move(nd); cap = cap ? cap * 2 : 2;
        d[n++] = v;
    }
};

struct SlowVec {
    std::unique_ptr<int[]> d;
    int n = 0, cap = 0, moves = 0;
    void push(int v) {
        if (n < cap) { d[n++] = v; return; }
        auto nd = std::make_unique<int[]>(cap + 1);
        for (int i = 0; i < n; ++i) nd[i] = d[i];
        moves += n; d = std::move(nd); cap = cap + 1;
        d[n++] = v;
    }
};

int main() {
    MiniVec v;
    SlowVec s;
    for (int i = 1; i <= 100; ++i) {
        v.push(i * 10);
        s.push(i * 10);
    }
    std::println("装了 {} 个，容量 {} 格，累计搬运 {} 次", v.n, v.cap, v.moves);
    std::println("坏版本装了 {} 个，容量 {} 格，累计搬运 {} 次", s.n, s.cap, s.moves);
    // 坏版本搬 4950 件，2 倍版本搬 126 件，差约 39 倍
    return 0;
}

